QS = [
    ('Hakeem Force Academy', 'The Constitution of 1956 was adopted by the Constituent Assembly of Pakistan on which date?', ['29 January 1956', '29 February 1956', '29 April 1956', '23 March 1956'], 1, 'The Constituent Assembly adopted the first Constitution on 29 February 1956 (1956 was a leap year).', 'It came into force on 23 March 1956, later celebrated as Republic Day.', 3423),
    ('Hakeem Force Academy', 'Which Prime Minister played the leading role in framing the Constitution of 1956?', ['Iskander Mirza', 'Muhammad Ali Bogra', 'Chaudhry Muhammad Ali', 'Huseyn Shaheed Suhrawardy'], 2, 'Chaudhry Muhammad Ali was Prime Minister when the Constituent Assembly passed the 1956 Constitution.', 'He also served as Finance Minister and Secretary General of the government earlier.', 1658),
    ('Hakeem Force Academy', 'On which date did the Constitution of 1956 come into force?', ['23 February 1956', '14 August 1956', '23 March 1956', '29 February 1956'], 2, 'The 1956 Constitution was enforced on 23 March 1956 and Pakistan became an Islamic Republic.', '23 March is celebrated as Pakistan Day, which also recalls the 1940 Lahore Resolution.', 3489),
    ('Hakeem Force Academy', 'The Constitution of 1956 was framed by the Constituent Assembly in the name of whom?', ['The people of Pakistan', 'The President', 'The Prime Minister', 'The Governor General'], 0, 'The Constitution was adopted in the name of the people of Pakistan, as the preamble says.', 'The Objective Resolution of 1949 was made its preamble basis.', -1),
    ('Hakeem Force Academy', 'The Constitution of 1956 received its assent from which office holder?', ['President', 'Governor General', 'Prime Minister', 'Chief Justice'], 1, 'The Governor General (Iskander Mirza) gave assent to the Constitution passed by the Constituent Assembly. He became the first President on 23 March 1956.', 'The office of Governor General was replaced by the President.', -1),
    ('Hakeem Force Academy', 'What name did the Constitution of 1956 give to the country?', ['Islamic Republic of Pakistan', 'Republic of Pakistan', 'Dominion of Pakistan', 'Federation of Pakistan'], 0, 'The 1956 Constitution declared Pakistan an Islamic Republic, the first in the world.', 'The 1962 Constitution first dropped the word Islamic from the name.', 264),
    ('Hakeem Force Academy', 'Which part of the Constitution of 1956 dealt with Fundamental Rights?', ['Part I', 'Part II', 'Part III', 'Part IV'], 1, 'Fundamental Rights were placed in Part II of the 1956 Constitution.', 'The Directive Principles of State Policy came in the following part.', -1),
    ('Hakeem Force Academy', 'Which form of government was provided by the Constitution of 1956?', ['Parliamentary', 'Presidential', 'Military', 'Monarchy'], 0, 'The 1956 Constitution set up a parliamentary system with a Prime Minister and cabinet responsible to the National Assembly.', 'The 1962 Constitution changed this to a presidential system.', 5100),
    ('Hakeem Force Academy', 'According to the Constitution of 1956, who was the Head of State?', ['President', 'Prime Minister', 'Governor General', 'Chief Justice'], 0, 'The President replaced the Governor General as constitutional Head of State.', 'Iskander Mirza was the first President of Pakistan.', -1),
    ('Hakeem Force Academy', 'What was the minimum age to become President under the Constitution of 1956?', ['35 years', '40 years', '45 years', '50 years'], 1, 'The 1956 Constitution required the President to be at least 40 years old and a Muslim.', 'The 1962 Constitution lowered the minimum age to 35.', 1635),
    ('Hakeem Force Academy', 'What type of legislature did the Constitution of 1956 provide?', ['Unicameral', 'Bicameral', 'Tricameral', 'No legislature'], 0, 'It provided a single-house National Assembly of 300 members, equally divided between East and West Pakistan.', "Pakistan's first bicameral legislature came with the 1973 Constitution.", 4990),
    ('Hakeem Force Academy', 'Which was the highest court of the country under the Constitution of 1956?', ['Federal Court', 'Supreme Court', 'High Court', 'Federal Shariat Court'], 1, 'The 1956 Constitution created the Supreme Court of Pakistan, replacing the Federal Court that existed since 1948. The source marked Federal Court, which is wrong.', 'The Federal Shariat Court was created much later, in 1980.', -1),
    ('Hakeem Force Academy', 'Which languages were made national languages by the Constitution of 1956?', ['Urdu and English', 'Urdu and Hindi', 'Urdu and Bengali', 'Urdu and Punjabi'], 2, 'Urdu and Bengali were declared the state languages in the 1956 Constitution, with English used officially for 20 years.', 'Bengali was recognised after the 1952 Language Movement.', 6223),
    ('Hakeem Force Academy', 'Which type of federal structure did the Constitution of 1956 provide?', ['Unitary', 'Federal', 'Confederal', 'Monarchical'], 1, 'It provided a federation of two wings, East and West Pakistan, with federal, provincial and concurrent lists.', 'Powers were distributed through three lists.', -1),
    ('Hakeem Force Academy', 'How many Articles and Parts did the Constitution of 1956 contain?', ['240 Articles and 10 Parts', '280 Articles and 7 Parts', '234 Articles and 13 Parts', '256 Articles and 11 Parts'], 2, 'The 1956 Constitution had 234 Articles, 13 Parts and 6 Schedules.', 'The 1973 Constitution has 280 Articles.', 1577),
    ('Hakeem Force Academy', 'For about how long did the Constitution of 1956 remain in force?', ['About 6 months', 'About 1 year and 6 months', 'About 2 years and 6 months', 'About 5 years'], 2, 'It was enforced on 23 March 1956 and abrogated on 7 October 1958, about two and a half years.', "It was the shortest-lived of Pakistan's three constitutions.", 4218),
    ('Hakeem Force Academy', 'On which date was the Constitution of 1956 abrogated?', ['7 October 1958', '7 June 1956', '7 July 1958', '27 October 1958'], 0, 'President Iskander Mirza abrogated it on 7 October 1958 and imposed martial law.', 'Ayub Khan became Chief Martial Law Administrator and removed Mirza on 27 October 1958.', 4047),
    ('Hakeem Force Academy', 'Which body enacted the Constitution of 1956?', ['Constituent Assembly', 'National Assembly', 'Federal Court', 'Council of Islamic Ideology'], 0, 'The second Constituent Assembly passed it, as the first one had been dissolved in 1954.', 'Governor General Ghulam Muhammad dissolved the first Constituent Assembly in October 1954.', -1),
    ('Hakeem Force Academy', 'What was the total strength of the National Assembly under the Constitution of 1956?', ['240 members', '310 members', '340 members', '400 members'], 1, 'It had 300 members, 150 from each wing, plus 10 seats reserved for women, so 310. The Constitution also kept parity between the wings.', 'Today the National Assembly has 336 seats.', -1),
    ('Hakeem Force Academy', 'How were members of the National Assembly elected under the Constitution of 1956?', ['Directly', 'Indirectly', 'By nomination', 'By the Governor General'], 0, 'The Constitution provided direct elections to the National Assembly, though no general election was held before it was abrogated.', 'The first direct adult-franchise general election was held in 1970.', -1),
    ('Hakeem Force Academy', 'What type of citizenship did the Constitution of 1956 provide?', ['Single citizenship', 'Dual citizenship', 'Provincial citizenship', 'Wing-wise citizenship'], 0, 'Pakistan had a single citizenship for all citizens, as in a federation like India but unlike the USA.', 'The 1973 Constitution also has a single citizenship.', -1),
    ('Hakeem Force Academy', 'Under the Constitution of 1956, how were powers divided in the federation?', ['All with the Centre', 'All with the Provinces', 'Divided between Centre and Provinces', 'All with the President'], 2, 'Powers were shared through a Federal List, a Provincial List and a Concurrent List.', 'The 1962 Constitution had only Central and Provincial subjects.', -1),
    ('Hakeem Force Academy', 'Under the Constitution of 1956, to whom was the Cabinet collectively responsible?', ['The President', 'The National Assembly', 'The Governor', 'The Chief Justice'], 1, 'In the parliamentary system the Cabinet led by the Prime Minister was answerable to the National Assembly.', 'The Prime Minister was the head of government.', -1),
    ('Hakeem Force Academy', 'On which date was the Constitution of 1962 enforced?', ['1 March 1962', '8 June 1962', '23 March 1962', '14 August 1962'], 1, 'President Ayub Khan promulgated it on 1 March 1962 and it came into force on 8 June 1962. Note the source gave 28 February, which is not the correct date.', 'Martial law was lifted when it came into force.', 4335),
    ('Hakeem Force Academy', 'In how many Parts was the Constitution of 1962 divided (it had 250 Articles)?', ['10 Parts', '12 Parts', '13 Parts', '9 Parts'], 1, 'The 1962 Constitution had 250 Articles, 12 Parts and 3 Schedules.', 'The 1956 Constitution had 234 Articles and 13 Parts.', -1),
    ('Hakeem Force Academy', 'Which form of government did the Constitution of 1962 provide?', ['Parliamentary', 'Presidential', 'Military', 'Monarchy'], 1, 'It created a strong presidential system with the President as Chief Executive.', 'There was no Prime Minister in the 1962 Constitution as originally framed.', 101),
    ('Hakeem Force Academy', 'How was the President elected under the Constitution of 1962?', ['Directly by all adult voters', 'Indirectly by an electoral college', 'By the National Assembly only', 'By the Supreme Court'], 1, 'The President was elected indirectly by an electoral college of Basic Democrats.', 'Ayub Khan won the 1965 election against Fatima Jinnah this way.', 139),
    ('Hakeem Force Academy', 'The electoral college under the Constitution of 1962 was originally formed of how many Basic Democrats?', ['40,000', '80,000', '120,000', '160,000'], 1, 'Originally 80,000 Basic Democrats (40,000 per wing) formed the electoral college.', 'It was later raised to 120,000 before the 1965 election.', -1),
    ('Hakeem Force Academy', 'What was the voting age under the Constitution of 1962?', ['25 years', '21 years', '20 years', '18 years'], 1, 'The 1962 Constitution set the minimum voting age at 21 years.', 'The voting age was lowered to 18 in 1973 and is now 18.', -1),
    ('Hakeem Force Academy', 'What was the minimum age for a person to be elected President under the Constitution of 1962?', ['30 years', '35 years', '40 years', '45 years'], 1, 'The 1962 Constitution required the President to be at least 35 years of age and a Muslim.', 'Under the 1956 Constitution it was 40 years.', 3383),
    ('Hakeem Force Academy', 'Under the Constitution of 1962, who had the power to dissolve the National Assembly?', ['The President', 'The Prime Minister', 'The Speaker', 'The Chief Justice'], 0, 'The President held the power to dissolve the Assembly, one of his wide powers. The source asked the Article number, which could not be verified.', 'Under the 1973 Constitution this power is in Article 58.', -1),
    ('Hakeem Force Academy', 'Under the Constitution of 1962, who could be impeached by the National Assembly?', ['President', 'Speaker', 'Chief Justice', 'Governor'], 0, 'The Constitution provided a process for impeaching the President, though it was very difficult to use.', 'In the 1973 Constitution the President is removed under Article 47.', -1),
    ('Hakeem Force Academy', 'The Constitution of 1962 provided a federation of the centre and how many provinces?', ['Two', 'Three', 'Four', 'One'], 0, 'The federation consisted of two provinces, East Pakistan and West Pakistan.', 'West Pakistan was a single province created through One Unit in 1955.', -1),
    ('Hakeem Force Academy', 'What was the original name of the country under the Constitution of 1962?', ['Republic of Pakistan', 'Islamic Republic of Pakistan', 'Islamic Democratic Pakistan', 'Federal Republic of Pakistan'], 0, 'The 1962 Constitution dropped the word Islamic and called the country the Republic of Pakistan.', 'The word Islamic was restored by an amendment.', 2124),
    ('Hakeem Force Academy', 'In which month of 1963 did the National Assembly pass the amendment restoring the name Islamic Republic of Pakistan?', ['December', 'October', 'August', 'March'], 0, 'The first Amendment Act was passed in December 1963 and restored the name Islamic Republic of Pakistan.', 'The amendment was formally assented in January 1964.', -1),
    ('Hakeem Force Academy', 'Who was the Chief Executive of the country under the Constitution of 1962?', ['President', 'Prime Minister', 'Governor General', 'Speaker'], 0, 'The President was both head of state and chief executive.', 'Ayub Khan was the first President under this Constitution.', 3913),
    ('Hakeem Force Academy', 'What was the term of office of the President under the Constitution of 1962?', ['4 years', '5 years', '6 years', '3 years'], 1, 'The President held office for five years.', 'The 1973 Constitution also gives a five-year term.', -1),
    ('Hakeem Force Academy', 'Which was the highest court of the country under the Constitution of 1962?', ['Supreme Court', 'Federal Court', 'Federal Shariat Court', 'High Court'], 0, 'The Supreme Court remained the apex court of the country.', 'The Supreme Court was first created by the 1956 Constitution.', -1),
    ('Hakeem Force Academy', 'What type of legislature did the Constitution of 1962 provide?', ['Unicameral', 'Bicameral', 'Tricameral', 'None'], 0, 'It provided a single-house National Assembly.', 'The Senate came only with the 1973 Constitution.', -1),
    ('Hakeem Force Academy', 'Up to which age could a Supreme Court judge serve under the Constitution of 1962?', ['60 years', '62 years', '65 years', '68 years'], 2, 'The 1962 Constitution set retirement of Supreme Court judges at 65 years.', 'Under the 1973 Constitution it is also 65 years.', -1),
    ('Hakeem Force Academy', 'Which languages were national languages under the Constitution of 1962?', ['Urdu only', 'Bengali only', 'Urdu and Bengali', 'Urdu and English'], 2, 'Urdu and Bengali were national languages, while English remained in official use.', 'Bengali was first recognised in 1956.', 2736),
    ('Hakeem Force Academy', 'Which system of local government did Ayub Khan make the base of the Constitution of 1962?', ['Basic Democracies', 'Local Bodies of 1979', 'Devolution Plan', 'Panchayat system'], 0, 'The Basic Democracies system of 1959 created union councils whose members formed the electoral college.', 'The Devolution Plan was introduced later, in 2001.', -1),
]
